import {demoState,applyScenario,plan} from './engine.mjs';import {gallons} from './units.mjs';
const $=id=>document.getElementById(id);const fmt=(n,d=0)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});const usd=n=>'$'+fmt(n,0);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current,settings;
function calculate(){const s=demoState();applyScenario(s,$('scenario').value);s.budget=Number($('budget').value);s.tolerance=Number($('tolerance').value);if(!Number.isFinite(s.budget)||s.budget<0||!Number.isFinite(s.tolerance)||s.tolerance<0||s.tolerance>100){$('summary').textContent='Enter a valid budget and risk threshold.';return;}let r;try{r=plan(s)}catch(e){$('summary').textContent='Optimization failed: '+e.message;return;}settings=s;current=r;render(r);}
function render(r){const available=r.totalSupply,firm=r.firm,hold=r.hold,free=r.unallocated;
$('available').textContent=fmt(gallons(available));$('firm').textContent=fmt(gallons(firm));$('hold').textContent=fmt(gallons(hold));$('ghg').textContent=fmt(r.expected,1);
$('legendFirm').textContent=fmt(gallons(firm))+' gal';$('legendHold').textContent=fmt(gallons(hold))+' gal';$('legendFree').textContent=fmt(gallons(free))+' gal';
$('stacked').innerHTML=[['firm',firm],['hold',hold],['free',free]].map(([cls,v])=>'<div class="'+cls+'" style="width:'+(available?v/available*100:0)+'%"></div>').join('');
$('cost').textContent=usd(r.cost);$('holdCost').textContent=usd(r.holdCost);$('remaining').textContent=usd(r.remainingBudget);
const risky=r.flightRows.filter(f=>f.routeRisk>settings.tolerance).length;
$('headline').textContent=firm>0?'Commit '+fmt(gallons(firm))+' gallons. Keep '+fmt(gallons(hold))+' flexible.':'No firm allocation is feasible under these settings.';
$('summary').textContent='The model recommends '+fmt(r.expected,1)+' tCO₂e of probability-weighted expected lifecycle reduction from firm allocations. '+risky+' route groups exceed the '+settings.tolerance+'% firm risk threshold. Conditional allocations are planning holds, not supplier-confirmed reservations.';
$('flights').innerHTML=r.flightRows.map((f,i)=>'<tr tabindex="0" data-index="'+i+'"><td><strong>'+escape(f.id)+'</strong><br>'+escape(f.origin)+' → '+escape(f.destination)+'</td><td>'+fmt(f.routeRisk,1)+'%</td><td>'+fmt(gallons(f.firm))+' gal</td><td>'+fmt(gallons(f.hold))+' gal</td><td>'+fmt(f.expected,1)+' t</td><td><span class="tag '+(f.status==='Commit'?'commit':f.status==='Keep flexible'?'flexible':'')+'">'+escape(f.status)+'</span></td></tr>').join('');
$('flights').querySelectorAll('tr').forEach(tr=>{const show=()=>explain(Number(tr.dataset.index));tr.addEventListener('click',show);tr.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show();}});});if(r.flightRows.length)explain(0);}
function explain(i){const f=current.flightRows[i];$('explanation').innerHTML='<strong>'+escape(f.origin+' → '+f.destination)+' · '+escape(f.status)+'</strong><ul>'+f.reasons.map(x=>'<li>'+escape(x)+'</li>').join('')+'</ul>';}
['scenario','budget','tolerance'].forEach(id=>$(id).addEventListener(id==='scenario'?'change':'input',calculate));
$('reset').addEventListener('click',()=>{$('scenario').value='mixed';$('budget').value=900000;$('tolerance').value=30;calculate();});
$('export').addEventListener('click',()=>{if(!current)return;const rows=[['Flight','Origin','Destination','Route Risk %','Firm US gal','Flexible US gal','Expected tCO2e','Status','Reason'],...current.flightRows.map(f=>[f.id,f.origin,f.destination,f.routeRisk.toFixed(2),gallons(f.firm).toFixed(2),gallons(f.hold).toFixed(2),f.expected.toFixed(3),f.status,f.reasons.join(' | ')])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='aerocommit-v2-decisions.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('menu').addEventListener('click',()=>{let expanded=$('sidebar').classList.toggle('open');$('menu').setAttribute('aria-expanded',String(expanded));});calculate();